func TestDynamicKey(t *testing.T) {
	got := string(pre.New().Dynamic("mykey").RenderBytes())
	want := `<pre id="mykey">
</pre>`
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

